    Image(systemName: index <= Int(badgeProgress.rating) ? "star.fill" : "star")
  }
}
.accessibilityRepresentation {
  Slider(value: $badgeProgress.rating, in: 0...5, step: 1.0) {
    Text("Rating")
  }
}

